B=[['拉丁 pes，属格 pedis，词干 ped-','脚、足；也能由支撑作用说物体的脚']]
PEDESTRIAN=B+[['拉丁 pedes → pedester／pedestri-','步行者 → 步行的；也有朴素、散文式的意思'],['英语 pedestrian（拉丁词干 + -an）','步行的；平淡无奇的'],['英语名词 pedestrian','行人、步行者']]
PEDAL=B+[['拉丁 pedalis → 晚期拉丁名词 pedale','脚的 → 用脚操作的东西'],['意大利 pedale → 法语 pédale → 英语 pedal','踏板；后来也作动词，踩踏板']]
PEDO=B+[['晚期拉丁 pedo／pedonem → 中世纪拉丁 pedonem','步行的人 → 徒步士兵']]
PIONEER=PEDO+[['古法语 peon／peonier、paonier → 法语 pionnier','步兵；为队伍开路的人'],['英语 pioneer〔名词〕','先驱、开拓者'],['英语 pioneer〔动词〕','率先开展、开辟']]
EXPEDLAT=B+[['拉丁 ex- 与 ped- 相关成分 → expedire','解除脚上的束缚；引申排除障碍、使就绪']]
EXPEDITE=EXPEDLAT+[['拉丁分词 expeditus → 英语 expedite','已解除束缚、就绪的 → 使事情加快办理']]
EXPEDITION=EXPEDLAT+[['拉丁 expeditio／expeditionem → 法语 expedicion／直接拉丁借入','准备出发、出征、执行行动'],['中古英语 expedicioun → expedition','有特定目的的远行；探险或考察队']]
EXPEDIENT=EXPEDLAT+[['拉丁现在分词 expediens／expedientem','有助于达到目的的、有利的'],['古法语 expedient／直接拉丁借入 → 英语 expedient','权宜的、合用的；后来也作名词指权宜之计']]
EXPEDIENCE=EXPEDLAT+[['拉丁 expediens → 晚期拉丁 expedientia','适用、有利 → 适宜性、利益'],['古法语 expedience → 中古英语 expedience','合用、权宜；看重实际便利']]
EXPEDITIOUS=EXPEDLAT+[['拉丁 expeditus → 中古英语 expedycius','就绪、合用、迅速的'],['英语 expeditious','办事迅速而有效率的']]
IMPLAT=B+[['拉丁 in- + ped- → impedire','使脚受束缚 → 阻碍、妨碍']]
IMPEDIMENT=IMPLAT+[['拉丁 impedimentum → 古法语 empedement／直接拉丁借入','妨碍前进的事物'],['中古英语 impediment → 英语 impediment','障碍；妨碍正常活动的困难']]
IMPEDE=IMPLAT+[['英语 impede','可由拉丁 impedire 借入；也有从较早英语 impediment 逆构的分析']]
IMPEACHLAT=B+[['拉丁 pedica → 晚期拉丁 impedicare','脚镣、绊索 → 束缚、缠住'],['古法语 empeechier／盎格鲁法语 empecher → 中古英语 empechen','阻碍、妨碍；法律上指责、控告']]
IMPEACH=A(IMPEACHLAT,'英语 impeach','正式指控公职人员；也可质疑证人的可信性')
VAMP=B+[['拉丁 pes → 古法语 pié；avant + pié → avantpié','脚 → 脚前部、鞋前帮'],['盎格鲁法语 vaum-pei／vampe → 中古英语 vaumpe → vamp','覆盖脚的鞋袜部分；鞋面前部'],['英语 vamp 的修补、拼凑用法 → 音乐用法','修补旧物 → 即兴补出、反复弹奏伴奏']]
BIPEDSTEM=A(B,'拉丁 bipes／biped-','双足的；两足动物')
BIPEDAL=A(BIPEDSTEM,'英语 bipedal（biped- + -al）','用两足行走的；现代构词可与 biped 对照')
QUADSTEM=A(B,'拉丁 quadrupes／quadruped-','四足的；四足动物')
QUAD=QUADSTEM+[['法语 quadrupède → 英语 quadruped','四足动物；也用于四足机器']]
